// This crate is entirely generated by `tonic-build` from `crates/proto/proto/*.proto`
// (see `build.rs`), so lints that only make sense for hand-written code are silenced
// crate-wide instead of per item. `result_large_err` fires on every
// `Result<_, tonic::Status>` in the generated service traits and cannot be addressed
// without boxing `tonic::Status` itself; `doc_lazy_continuation` fires on the generated
// doc comments.
#![allow(clippy::result_large_err)]

#[allow(clippy::doc_lazy_continuation)]
pub mod common {
    tonic::include_proto!("coldstore.common");
}

#[allow(clippy::doc_lazy_continuation)]
pub mod metadata {
    tonic::include_proto!("coldstore.metadata");
}

#[allow(clippy::doc_lazy_continuation)]
pub mod scheduler {
    tonic::include_proto!("coldstore.scheduler");
}

#[allow(clippy::doc_lazy_continuation)]
pub mod cache {
    tonic::include_proto!("coldstore.cache");
}

#[allow(clippy::doc_lazy_continuation)]
pub mod tape {
    tonic::include_proto!("coldstore.tape");
}
